starterCode:
fun canNotify(sdk: Int, granted: Boolean): Boolean {
    // до Android 13 (SDK 33) разрешение не требуется
}

solution:
fun canNotify(sdk: Int, granted: Boolean): Boolean {
    if (sdk < 33) return true
    return granted
}

